LIMIT 1

SELECT 
FROM learning_note
WHERE user_id = #{userId}
  AND type = #{type}
  AND deleted_at IS NULL
ORDER BY updated_at DESC, id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1)
FROM learning_note
WHERE user_id = #{userId}
  AND type = #{type}
  AND deleted_at IS NULL

